   remainingMs:['announcement','countdown'].includes(this.phase)?Math.max(0,this.phaseEndsTick-tick)*DT*1000:0,
   players:this.records.map((p,slot)=>({...p,present:this.presence.has(slot),survivalMs:this.survivalMs(p.infectedTick??this.stoppedTick??tick,slot),survivalPoints:this.survivalPoints(p.infectedTick??this.stoppedTick??tick,slot),slot,state:p.infectedTick===null?'healthy':tick<(p.infectiousTick??tick)?'transforming':'infectious',patientZero:slot===this.patientZero,totalPoints:this.totals[slot],finalPlace:1+this.totals.filter(total=>total>this.totals[slot]).length})),
   roundWinners:[...this.roundWinners],matchWinners:this.phase==='match-results'?this.totals.flatMap((points,i)=>points===highest?[i]:[]):[]};
 }
}

