 advanceClock(tick:number){if(this.phase==='announcement'&&tick>=this.phaseEndsTick){this.phase='countdown';this.phaseEndsTick+=this.timing.countdownTicks;}if(this.phase==='countdown'&&tick>=this.phaseEndsTick){this.phase='playing';this.startedTick=tick;this.presence.start(tick);this.lastTick=tick;}}
