 const me=state.players[local];el('live-score').textContent=local===freeze.freezer?`FREEZER · ${freeze.freezeCount} freezes`:freeze.frozen[local]?'FROZEN · TEAMMATE RESCUE ONLY':me?`UNFROZEN · ${points(me.survivalPoints)} pts`:'';el('infection-feedback').textContent=freeze.protectedUntil[local]>state.tick?`RESCUED · ${((freeze.protectedUntil[local]-state.tick)/60).toFixed(1)}s protection`:'';if(!results)return;
