import {test} from 'node:test';import assert from 'node:assert/strict';import {Vec2} from 'planck';import {Simulation} from '../src/simulation/world';import {setSimulationArena} from '../src/simulation/arena-adapter';import {applyChaos} from '../src/chaos/registry';import {ARENA_CHAOS as A} from '../src/chaos/arena-chaos';import {EXTREME_CHAOS as E} from '../src/chaos/extreme-chaos';import {FROG_CHAOS as F} from '../src/chaos/frog-chaos';import {capture,restore} from '../src/simulation/state';import {readFileSync} from 'node:fs';import {createHash} from 'node:crypto';
function grounded(arena='canopy'){const s=new Simulation();setSimulationArena(s,arena);s.frogs.slice(1).forEach(f=>f.body.setActive(false));s.frogs[0].body.setTransform(Vec2(20,21.05),0);for(let i=0;i<12;i++)s.step();return s;}
function windRun(direction:number,speed:number,before=false){const saved={...A};try{if(before)Object.assign(A,{windAcceleration:18,windGroundAcceleration:64});const s=grounded();applyChaos(s,['windy_weather']);if(before)s.arenaChaos.runningScale=()=>1;s.tick+=direction===1?A.windWarning:A.windPeriod+A.windWarning;const f=s.frogs[0];f.body.setLinearVelocity(Vec2(-direction*speed,0));const start=f.body.getPosition().x;let late=0;for(let i=0;i<150;i++){s.setInput(0,{x:-direction,y:0,held:false});s.step();if(i>=120)late+=f.body.getLinearVelocity().x;}return{distance:f.body.getPosition().x-start,lateSpeed:late/30};}finally{Object.assign(A,saved);}}
test('normal running makes slow counter-wind progress in either direction, from rest or an already-fast run; calm/expiry restores normal',()=>{const before=windRun(1,0,true),after=windRun(1,0);console.log('WIND',JSON.stringify({before,after}));assert.ok(before.distance>0);for(const direction of[1,-1])for(const speed of[0,6]){const r=windRun(direction,speed);assert.ok(r.distance*direction<0,JSON.stringify(r));assert.ok(r.lateSpeed*direction<-.2&&r.lateSpeed*direction>-2,JSON.stringify(r));}const s=grounded();applyChaos(s,['windy_weather']);s.tick+=A.windWarning;assert.equal(s.arenaChaos.runningScale(-1),.25);assert.equal(s.arenaChaos.runningScale(1),1);s.tick+=A.windGust;assert.equal(s.arenaChaos.runningScale(-1),1);applyChaos(s,[]);assert.equal(s.arenaChaos.runningScale(-1),1);});
function pondBounce(speed:number,steer=false){const old=E.pogoSpeed;try{E.pogoSpeed=speed;const s=grounded('sunny-pond'),f=s.frogs[0];f.body.setTransform(Vec2(9.7,21.05),0);f.body.setLinearVelocity(Vec2(0,0));applyChaos(s,['pogo_panic']);let apex=100,landed=false;for(let i=0;i<90;i++){s.setInput(0,{x:steer&&i>=29?-1:0,y:0,held:false});s.step();apex=Math.min(apex,f.body.getPosition().y);if(f.stickyMud&&f.grounded&&f.body.getPosition().y<18){landed=true;break;}}return{apex,landed};}finally{E.pogoSpeed=old;}}
test('slightly higher immediate Pogo clears Sunny Pond first rock ledge through normal steering, with identical landing timing and cooldown',()=>{const before=pondBounce(14.25),after=pondBounce(E.pogoSpeed),route=pondBounce(E.pogoSpeed,true);console.log('POGO',JSON.stringify({before,after,route}));assert.ok(before.apex>16.95);assert.ok(after.apex<16.95);assert.ok(route.landed,JSON.stringify(route));assert.equal(E.pogoSpeed,15.25);assert.equal(E.pogoCooldownTicks,12);assert.equal(E.pogoSeparationTicks,4);});
test('bubbles spawn every .8 seconds but retain max four, six-second trapping, five presses and recapture protection',()=>{const s=grounded();applyChaos(s,['bubble_trouble']);const counts=[],start=s.tick;for(const age of[0,47,48,96,144,192,240]){s.tick=start+age;s.frogChaos.before();counts.push(s.frogChaos.capture()!.bubbles.length);}assert.deepEqual(counts,[1,1,2,3,4,4,4]);assert.equal(F.bubblePeriod,48);assert.equal(F.bubbleMaximum,4);assert.equal(F.bubbleTrap,360);assert.equal(F.bubbleEscapePresses,5);assert.equal(F.bubbleRecapture,60);});
test('wind running resistance and Pogo/bubbles restore identically from authoritative snapshots',()=>{for(const ids of[['windy_weather','pogo_panic','bubble_trouble'],['windy_weather','butterfeet','mega_tongues']]){const a=grounded(),b=grounded();applyChaos(a,ids as any);applyChaos(b,ids as any);a.tick+=A.windWarning;restore(b,capture(a));for(let i=0;i<60;i++){for(const s of[a,b]){s.setInput(0,{x:-1,y:0,held:false});s.step();}}assert.deepEqual(capture(a),capture(b));}});
test('gusts have arena-wide animated streaks plus a readable direction/countdown label; every unrelated source remains exact',()=>{const art=readFileSync('src/presentation/courtyard.ts','utf8');assert.ok(art.includes('GUSTING'));assert.ok(art.includes('this.scene.time.now*.32'));assert.ok(art.includes('i<28'));const m=JSON.parse(readFileSync('docs/modifier-tweaks-preservation.json','utf8')),h=(b:any)=>createHash('sha256').update(b).digest('hex');for(const[p,v]of Object.entries(m.protected))assert.equal(h(readFileSync(p)),v,p);for(const[p,v]of Object.entries(m.files)as[string,any][]){assert.equal(h(readFileSync(p)),v.afterSha256,p);assert.equal(h(v.original),v.beforeSha256,p);}});

