import {test} from 'node:test';import assert from 'node:assert/strict';import {Vec2} from 'planck';import {FreezeRules,FREEZE} from '../src/game/freeze-tag';import {syncFrozenBodies,stepFrozenBodies} from '../src/game/frozen-bodies';import {Simulation} from '../src/simulation/world';import {sizeSimulation} from '../src/simulation/roster';import {setSimulationArena} from '../src/simulation/arena-adapter';import {arenaList} from '../src/simulation/arenas';import {capture,restore} from '../src/simulation/state';import {Predictor} from '../src/network/predictor';import {Moments} from '../src/presentation/moments';
const timing={...FREEZE,announcementTicks:1,countdownTicks:1};function rules(n=3){const r=new FreezeRules(Array.from({length:n},(_,i)=>i),0,timing);r.advanceClock(2);return r;}
test('two-player first body freeze ends round; no thaw or 5-point clear bonus; scoring and rotation',()=>{const r=rules(2);r.infect(62,[[0,1]]);assert.equal(r.phase,'round-results');assert.equal(r.view(62).players[0].roundPoints,3);assert.equal(r.view(62).players[1].roundPoints,1);assert.deepEqual(r.roundWinners,[0]);r.infect(10000,[]);assert.equal(r.records[1].frozen,true);r.next(10000);assert.equal(r.patientZero,1);r.advanceClock(10002);r.infect(10062,[[0,1]]);r.next(10062);assert.equal(r.phase,'match-results');assert.deepEqual(r.view(10062).matchWinners,[0,1]);});
test('no automatic thaw; teammates only; rescue grace and continued-contact re-freeze',()=>{const r=rules();r.infect(62,[[0,1]]);r.infect(1000,[]);assert.ok(r.records[1].frozen);r.infect(1001,[[0,1]]);assert.ok(r.records[1].frozen);r.infect(1002,[[2,1]]);assert.equal(r.records[1].frozen,false);assert.equal(r.records[1].protectedUntil,1062);r.infect(1061,[[0,1]]);assert.equal(r.records[1].frozen,false);r.infect(1062,[[0,1]]);assert.equal(r.records[1].frozen,true);assert.equal(r.freezeCount,2);assert.equal(r.records[2].rescues,1);});
test('freeze precedes rescue; callback ordering cannot allow newly frozen runner to rescue',()=>{const a=rules(4),b=rules(4);for(const r of [a,b])r.infect(62,[[0,1]]);a.infect(63,[[1,2],[0,2]]);b.infect(63,[[0,2],[1,2]]);assert.deepEqual(a.view(63),b.view(63));assert.ok(a.records[1].frozen);assert.ok(a.records[2].frozen);a.infect(64,[[1,3],[2,3]]);assert.ok(!a.records[1].frozen&&!a.records[2].frozen);});
test('same-tick all frozen ends; 3–8 clear bonus; authoritative timeout escape winners and paused survival',()=>{const r=rules(4);r.infect(62,[[0,1],[0,2]]);r.infect(122,[[3,1]]);r.infect(182,[]);assert.equal(r.view(182).players[1].survivalPoints,2);assert.equal(r.view(182).players[2].survivalPoints,1);r.infect(3602,[[0,3]]);assert.equal(r.reason,'timeout');assert.deepEqual(r.roundWinners,[1,3]);assert.equal(r.view(3602).players[0].roundPoints,6);for(const n of [3,4,8]){const all=rules(n);all.infect(62,Array.from({length:n-1},(_,i)=>[0,i+1]as[number,number]));assert.equal(all.reason,'all-frozen');assert.equal(all.points(0),3*(n-1)+5);assert.equal(all.phase,'round-results');}});
test('frozen bodies stay immobile across every arena/material, restore mass on rescue and cannot be tongue anchors',()=>{for(const arena of arenaList){const s=new Simulation();sizeSimulation(s,3);setSimulationArena(s,arena.id);for(const material of [arena.solids[4],...arena.solids.filter(r=>r.surface)]){s.frogs[1].body.setTransform(Vec2(material.x,material.y-material.h/2-.47),0);s.frogs[0].body.setTransform(Vec2(material.x-3,material.y-2),0);const p=s.frogs[1].body.getPosition().clone(),mass=s.frogs[1].body.getMass();s.frogs[1].body.setLinearVelocity(Vec2(30,-20));syncFrozenBodies(s,[false,true,false]);for(let tick=0;tick<240;tick++){s.setInput(1,{x:1,y:-1,held:tick%2===0});stepFrozenBodies(s,[false,true,false],()=>s.step());assert.deepEqual(s.frogs[1].body.getPosition(),p);assert.equal(s.frogs[1].tongue,undefined);assert.equal(s.frogs[1].slipperySoap,undefined);assert.equal(s.frogs[1].stickyMud,undefined);assert.ok(Number.isFinite(s.frogs[0].body.getPosition().x));}syncFrozenBodies(s);assert.equal(s.frogs[1].body.isDynamic(),true);assert.equal(s.frogs[1].body.getMass(),mass);s.setInput(1,{x:1,y:0,held:false});for(let i=0;i<20;i++)s.step();assert.ok(s.frogs[1].body.getPosition().x!==p.x);}}});
test('freeze detaches incoming/outgoing joints; pinned-state prediction and terrain indexing stay consistent',()=>{const s=new Simulation();sizeSimulation(s,3);setSimulationArena(s,'sunny-pond');s.frogs[0].body.setTransform(Vec2(12,9),0);s.frogs[1].body.setTransform(Vec2(14,9),0);s.setInput(0,{x:1,y:0,held:true});for(let i=0;i<12;i++)s.step();assert.ok(s.frogs[0].tongue);syncFrozenBodies(s,[false,true,false]);assert.equal(s.frogs[0].tongue,undefined);const snapshot={state:capture(s),frozen:[false,true,false],serverTime:1000,ack:[0,0,0],connected:[true,true,true],tickMs:{p50:0,p95:0,p99:0,max:0},overruns:0,resetId:0};const predictor=new Predictor();predictor.slot=1;setSimulationArena(predictor.sim,'sunny-pond');predictor.reconcile(snapshot,1100,0);predictor.add({seq:1,at:1100,input:{x:1,y:-1,held:true}});predictor.advance(1200);assert.equal(predictor.sim.frogs[1].body.getPosition().x,s.frogs[1].body.getPosition().x);assert.equal(predictor.sim.frogs[1].body.getPosition().y,s.frogs[1].body.getPosition().y);syncFrozenBodies(s);const fresh=new Simulation();setSimulationArena(fresh,'sunny-pond');restore(fresh,capture(s));assert.deepEqual(capture(fresh),capture(s));});
