test('Freeze and Classic pause only absent slots, retain mode status, and do not change connected scoring',()=>{for(const r of[new FreezeRules([0,1,2],0,{...timing,roundTicks:3600,protectionTicks:60,pointsPerSecond:1,freezePoints:3,clearBonus:5}),new ClassicRules([0,1,2],0,{...timing,roundTicks:3600,pointsPerSecond:1})]){r.advanceClock(0);r.infect(60,[]);r.presence.set(1,false,60,true);r.infect(180,[]);assert.equal(r.view(180).players[1].survivalPoints,1);assert.equal(r.view(180).players[2].survivalPoints,3);r.presence.set(1,true,180,true);r.infect(240,[]);assert.equal(r.view(240).players[1].survivalPoints,2);}});
