test('Escape/menu/help/leave clear held input, suppress gameplay keys, retain mobile access and stay available on lobby transition',()=>{const old=(globalThis as any).document,elements=new Map<string,any>(),listeners=new Map<string,Function[]>();function element(id:string){if(elements.has(id))return elements.get(id);const e:any={id,open:false,hidden:false,parentElement:null,textContent:'',onclick:undefined,cloneNode(){return element('clone');},removeAttribute(){},append(child:any){child.parentElement=e;},showModal(){e.open=true;},close(){e.open=false;},addEventListener(type:string,fn:Function){e[type]=fn;}};elements.set(id,e);return e;}const doc:any={getElementById:element,querySelector:element,activeElement:{blur(){}},addEventListener(type:string,fn:Function){listeners.set(type,[...(listeners.get(type)??[]),fn]);}};(globalThis as any).document=doc;let cleared=0,left=0;try{const guide=new PlayerGuide(()=>cleared++);guide.leaveAction=()=>left++;guide.update('game',true);const event:any={code:'Escape',repeat:false,preventDefault(){},stopPropagation(){}};for(const fn of listeners.get('keydown')!)fn(event);assert.ok(element('game-menu').open);assert.ok(guide.blocking);assert.equal(cleared,1);let blocked=false;for(const fn of listeners.get('keydown')!)fn({code:'KeyD',stopPropagation(){blocked=true;}});assert.ok(blocked);element('menu-help').onclick();assert.ok(element('help-dialog').open);assert.equal(element('game-menu').open,false);element('help-close').onclick();assert.equal(guide.blocking,false);element('help').onclick();assert.ok(element('game-menu').open);element('menu-leave').onclick();assert.ok(element('leave-dialog').open);element('leave-confirm').onclick();assert.equal(left,1);assert.equal(guide.blocking,false);element('help').onclick();guide.update('lobby',false);assert.equal(guide.blocking,true);element('menu-resume').onclick();assert.equal(guide.blocking,false);assert.equal(element('leave').parentElement,element('.lobby-primary'));}finally{(globalThis as any